INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(615839, 63864, 772, '<td valign="top">This photo doesn''t make me wonder what is going on outside of the frame but it''s a great photo.. = 10</td>', 'This photo doesn''t make me wonder what is going on outside of the frame but it''s a great photo.. = 10', '2004-03-10 00:06:44.000000', NULL, 1),
(615840, 63585, 16216, '<td valign="top">Nice capture but I am a little disturbed by the sun flare and you caught just a bit of something at about 2 oclock edge</td>', 'Nice capture but I am a little disturbed by the sun flare and you caught just a bit of something at about 2 oclock edge', '2004-03-10 00:07:53.000000', NULL, 1),
(615841, 63880, 10170, '<td valign="top">Very sexy, very seductive, has caught the feeling very well indeed, and very nicely the implied erotisism is off screen.  Love the lighting here as well.  Excellent shot.  I was going to do similar, but using legs to top of thighs, but am glad I didn;t as it would not have been nearly as effective as this.  10.</td>', 'Very sexy, very seductive, has caught the feeling very well indeed, and very nicely the implied erotisism is off screen.  Love the lighting here as well.  Excellent shot.  I was going to do similar, but using legs to top of thighs, but am glad I didn;t as it would not have been nearly as effective as this.  10.', '2004-03-10 00:08:27.000000', NULL, 1),
(615844, 63913, 16216, '<td valign="top">I am not convinced this really meets the challange, Nice House though</td>', 'I am not convinced this really meets the challange, Nice House though', '2004-03-10 00:08:59.000000', NULL, 1),
(615847, 63428, 17166, '<td valign="top">Nice take on the theme, but the focus is a little too soft.</td>', 'Nice take on the theme, but the focus is a little too soft.', '2004-03-10 00:12:15.000000', NULL, 1),
(615850, 63841, 10170, '<td valign="top">Ok, really taken by this one.  It has the off screen expectation perfectly.  Technique is flawless, and that blue haze to the left is very effective.  Truly excellent shot.  10.</td>', 'Ok, really taken by this one.  It has the off screen expectation perfectly.  Technique is flawless, and that blue haze to the left is very effective.  Truly excellent shot.  10.', '2004-03-10 00:13:27.000000', NULL, 1),
(615851, 63409, 17166, '<td valign="top">I like the noise/grain in this - really gives it that sort of 40''s-50''s photojournalism flavor.</td>', 'I like the noise/grain in this - really gives it that sort of 40''s-50''s photojournalism flavor.', '2004-03-10 00:14:18.000000', NULL, 1),
(615853, 63889, 10170, '<td valign="top">Very clever indeed, I absolutely love it.  Great lighting and I like the colour tone you selected here.  So simple, yet so very effective.  10.</td>', 'Very clever indeed, I absolutely love it.  Great lighting and I like the colour tone you selected here.  So simple, yet so very effective.  10.', '2004-03-10 00:14:27.000000', NULL, 1),
(615854, 63575, 772, '<td valign="top">:-)) - 10</td>', ':-)) - 10', '2004-03-10 00:14:28.000000', NULL, 1),
(615855, 63941, 15768, '<td valign="top">should have increased depth of focus</td>', 'should have increased depth of focus', '2004-03-10 00:15:04.000000', NULL, 1),
(615858, 63585, 17037, '<td valign="top">I like this ...clean ... simple....well photographed ... jumps up  . and the eye is so clear!  Good job!</td>', 'I like this ...clean ... simple....well photographed ... jumps up  . and the eye is so clear!  Good job!', '2004-03-10 00:17:17.000000', NULL, 1),
(615861, 63835, 17037, '<td valign="top">Got to love the dogs.  Nice shot.  Wish dog in fron were in perfect focus!</td>', 'Got to love the dogs.  Nice shot.  Wish dog in fron were in perfect focus!', '2004-03-10 00:19:05.000000', NULL, 1),
(615863, 63384, 10943, '<td valign="top">Oooh, that''s a good one for this challenge!  Makes me wonder what on earth he''s photographing!  Great focus and color.  8</td>', 'Oooh, that''s a good one for this challenge!  Makes me wonder what on earth he''s photographing!  Great focus and color.  8', '2004-03-10 00:20:14.000000', NULL, 1),
