(615872, 63434, 10943, '<td valign="top">It seems the focus of this image is in the image, instead of past the edge of it...</td>', 'It seems the focus of this image is in the image, instead of past the edge of it...', '2004-03-10 00:23:18.000000', NULL, 1),
(615874, 63865, 17037, '<td valign="top">Good idea, but as someone told me ... you can''t realy on the title.  I can see the camera in her eye .. which is great photography, but it takes away from the seductive message you are trying to convey.</td>', 'Good idea, but as someone told me ... you can''t realy on the title.  I can see the camera in her eye .. which is great photography, but it takes away from the seductive message you are trying to convey.', '2004-03-10 00:23:42.000000', NULL, 1),
(615875, 63840, 15934, '<td valign="top">I like your composition and lighting.</td>', 'I like your composition and lighting.', '2004-03-10 00:23:45.000000', NULL, 1),
(615877, 63247, 10943, '<td valign="top">Aww, why so small?  It looks like a nice pic from what I can see, I just can''t see much detail because of the size...7</td>', 'Aww, why so small?  It looks like a nice pic from what I can see, I just can''t see much detail because of the size...7', '2004-03-10 00:24:08.000000', NULL, 1),
(615878, 63354, 17037, '<td valign="top">Dogs are a shoo in!  Well done...  I think he (she?) wants a treat!  &lt;grin&gt;</td>', 'Dogs are a shoo in!  Well done...  I think he (she?) wants a treat!  <grin>', '2004-03-10 00:24:09.000000', NULL, 1),
(615879, 63787, 15934, '<td valign="top">This is a beautiful picture!</td>', 'This is a beautiful picture!', '2004-03-10 00:24:13.000000', NULL, 1),
