(615975, 63841, 15934, '<td valign="top">Nice photo, I assume it was done like EddyG''s "Almost Gone" //www.dpchallenge.com/image.php?IMAGE_ID=59658.</td>', 'Nice photo, I assume it was done like EddyG''s "Almost Gone" //www.dpchallenge.com/image.php?IMAGE_ID=59658.', '2004-03-10 00:53:26.000000', NULL, 1),
(615978, 63835, 10943, '<td valign="top">8</td>', '8', '2004-03-10 00:55:43.000000', NULL, 1),
