(615980, 63332, 15934, '<td valign="top">This is my favorite dog picture in this challenge!</td>', 'This is my favorite dog picture in this challenge!', '2004-03-10 00:56:52.000000', NULL, 1),
(615982, 63209, 15934, '<td valign="top">Nice composition, the white space to the right is quite nice.  And a cute dog to boot.</td>', 'Nice composition, the white space to the right is quite nice.  And a cute dog to boot.', '2004-03-10 01:00:10.000000', NULL, 1),
(615989, 63766, 7350, '<td valign="top">Interesting composition.  I feel that the colors are a little flat.</td>', 'Interesting composition.  I feel that the colors are a little flat.', '2004-03-10 01:08:28.000000', NULL, 1),
