(616160, 63835, 18213, '<td valign="top">Maby a ribbon</td>', 'Maby a ribbon', '2004-03-10 04:13:20.000000', NULL, 1),
(616162, 63180, 16957, '<td valign="top">Little implication of anything happening past the edge of the frame. Otherwise a competent composition that woudl perhaps benefit from having the scoop separated from the cone?</td>', 'Little implication of anything happening past the edge of the frame. Otherwise a competent composition that woudl perhaps benefit from having the scoop separated from the cone?', '2004-03-10 04:29:22.000000', NULL, 1),
