(616877, 63428, 10339, '<td valign="top">Nice picture - appears to be a lot of digital ''noise'' in the picture. I really like the colors of the girl''s outfit and the way it matches the tones of the water in the background.</td>', 'Nice picture - appears to be a lot of digital ''noise'' in the picture. I really like the colors of the girl''s outfit and the way it matches the tones of the water in the background.', '2004-03-10 14:29:14.000000', NULL, 1),
(616880, 63373, 17166, '<td valign="top">The one facing the other way looks so sad... good photo.  Wish it had a little more depth of field.</td>', 'The one facing the other way looks so sad... good photo.  Wish it had a little more depth of field.', '2004-03-10 14:31:43.000000', NULL, 1),
(616881, 63955, 18202, '<td valign="top">haha brilliant!</td>', 'haha brilliant!', '2004-03-10 14:32:53.000000', NULL, 1),
(616882, 63402, 10339, '<td valign="top">IMO the crop on the left seems too close.</td>', 'IMO the crop on the left seems too close.', '2004-03-10 14:33:10.000000', NULL, 1),
