(616894, 63552, 17166, '<td valign="top">Very original approach to the topic.</td>', 'Very original approach to the topic.', '2004-03-10 14:40:05.000000', NULL, 1),
(616904, 63266, 17550, '<td valign="top">Beautiful, beautiful shot!!! A 10 and added to my favourite photographs <br/> <br/>I would have cropped the image in both left and right sides but I still like the subject so much it gets a 10</td>', 'Beautiful, beautiful shot!!! A 10 and added to my favourite photographs  I would have cropped the image in both left and right sides but I still like the subject so much it gets a 10', '2004-03-10 14:46:30.000000', NULL, 1),
