(616913, 63945, 17974, '<td valign="top">neat perspective on an ordinary event.</td>', 'neat perspective on an ordinary event.', '2004-03-10 14:52:20.000000', NULL, 1),
(616914, 63373, 17974, '<td valign="top">great photo, but I don''t "see" the expectation</td>', 'great photo, but I don''t "see" the expectation', '2004-03-10 14:52:51.000000', NULL, 1),
(616915, 63198, 17974, '<td valign="top">interesting take on the challenge.</td>', 'interesting take on the challenge.', '2004-03-10 14:53:33.000000', NULL, 1),
(616916, 63900, 17550, '<td valign="top">Beautiful shot! One thing though -- I''m not sure the expectation here is off-screen. I love the sillouette of the boy and the colours -- for that I still give you very high marks</td>', 'Beautiful shot! One thing though -- I''m not sure the expectation here is off-screen. I love the sillouette of the boy and the colours -- for that I still give you very high marks', '2004-03-10 14:53:50.000000', NULL, 1),
(616920, 63930, 17550, '<td valign="top">Wow! I love how the man blends into the statues...I think it''s great how you managed to convert a somewhat interesting 3D subject into a very visually appealing 2D photograph Just not sure where the expectation is....</td>', 'Wow! I love how the man blends into the statues...I think it''s great how you managed to convert a somewhat interesting 3D subject into a very visually appealing 2D photograph Just not sure where the expectation is....', '2004-03-10 14:55:24.000000', NULL, 1);
