INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(617253, 63575, 5391, '<td valign="top">Good shot - made me laugh.  Thank you for choosing the "off" screen challenge to enter this in (as opposed to an "on" screen challenge which would be a different picture all together.  This is REALLY funny.  I wouldn''t mind seeing the whites whitened up a bit, but overall I love it.</td>', 'Good shot - made me laugh.  Thank you for choosing the "off" screen challenge to enter this in (as opposed to an "on" screen challenge which would be a different picture all together.  This is REALLY funny.  I wouldn''t mind seeing the whites whitened up a bit, but overall I love it.', '2004-03-10 17:30:40.000000', NULL, 1),
(617254, 63955, 327, '<td valign="top">Well done, really nice. Hope you do well.</td>', 'Well done, really nice. Hope you do well.', '2004-03-10 17:31:00.000000', NULL, 1),
(617255, 63864, 327, '<td valign="top">Wow....just an emotional shot!! Fantastic.</td>', 'Wow....just an emotional shot!! Fantastic.', '2004-03-10 17:31:31.000000', NULL, 1),
(617258, 63843, 327, '<td valign="top">I like this and scored it an 8. I don''t like the frame. It''s too ornate for this man.</td>', 'I like this and scored it an 8. I don''t like the frame. It''s too ornate for this man.', '2004-03-10 17:34:43.000000', NULL, 1),
(617259, 63266, 327, '<td valign="top">I wish a sexy 23 year old walks in the scene, give him a big kiss and they have coffee together! LOL Great shot. I love the focus, the desaturation is awesome.<br/>Love it.</td>', 'I wish a sexy 23 year old walks in the scene, give him a big kiss and they have coffee together! LOL Great shot. I love the focus, the desaturation is awesome.Love it.', '2004-03-10 17:36:19.000000', NULL, 1),
(617260, 63787, 327, '<td valign="top">Nice clean focus, light and colors. Awesome shot.</td>', 'Nice clean focus, light and colors. Awesome shot.', '2004-03-10 17:36:59.000000', NULL, 1),
(617261, 63944, 5391, '<td valign="top">A well-shot, expressive piece that fits the challenge perfectly.  One of the few in this challenge I''ve really enjoyed looking at.  Great composition that brings our attention to his eyes, wonderful exposure getting the whole face lit nicely without burning out the blinds, and the expressive look on the model''s face that really makes you wonder what he''s looking at or up to.  10</td>', 'A well-shot, expressive piece that fits the challenge perfectly.  One of the few in this challenge I''ve really enjoyed looking at.  Great composition that brings our attention to his eyes, wonderful exposure getting the whole face lit nicely without burning out the blinds, and the expressive look on the model''s face that really makes you wonder what he''s looking at or up to.  10', '2004-03-10 17:38:22.000000', NULL, 1),
(617263, 63895, 5391, '<td valign="top">Beautiful, moody shot.  I really like the crooked angle you''ve chosen to give this image a bit of punch.  The backlight serves the subject well, and you''ve captured an excellent exposure with that sky, while still getting detail in all of the dark areas.  Good work!  9</td>', 'Beautiful, moody shot.  I really like the crooked angle you''ve chosen to give this image a bit of punch.  The backlight serves the subject well, and you''ve captured an excellent exposure with that sky, while still getting detail in all of the dark areas.  Good work!  9', '2004-03-10 17:39:56.000000', NULL, 1),
(617264, 63317, 16478, '<td valign="top">And the interesting thing off screen is?</td>', 'And the interesting thing off screen is?', '2004-03-10 17:41:28.000000', NULL, 1),
(617265, 63468, 5391, '<td valign="top">I''m not entirely sure how I find this fitting with the theme of the challenge, but it''s such a great shot I''m giving it an 8, regardless.  Excellent use of composition, and the sharpness is really eye-catching.  Great shot!</td>', 'I''m not entirely sure how I find this fitting with the theme of the challenge, but it''s such a great shot I''m giving it an 8, regardless.  Excellent use of composition, and the sharpness is really eye-catching.  Great shot!', '2004-03-10 17:42:02.000000', NULL, 1),
(617267, 63867, 509, '<td valign="top">Nice expressions, good composition, though I''m not sure if I''d prefer the background as is or with clouds. -8-</td>', 'Nice expressions, good composition, though I''m not sure if I''d prefer the background as is or with clouds. -8-', '2004-03-10 17:48:03.000000', NULL, 1),
(617269, 63633, 509, '<td valign="top">Sorry, but there isn''t much "off screen expectation".  Maybe a view of the side of the dogs head with a focused glance on his/her face would better convey the message.  The colors are pretty bland as well.  I think the dog could have made a good subject, but the presentation here is lacking.</td>', 'Sorry, but there isn''t much "off screen expectation".  Maybe a view of the side of the dogs head with a focused glance on his/her face would better convey the message.  The colors are pretty bland as well.  I think the dog could have made a good subject, but the presentation here is lacking.', '2004-03-10 17:50:36.000000', NULL, 1),
(617272, 63798, 509, '<td valign="top">Nice ice cream shot.  I would have preferred to see a bit more of the icecream at the top (still hiding whether or not it has a cherry of course).  A closer crop on the bottom would eliminate the light reflection on the table.</td>', 'Nice ice cream shot.  I would have preferred to see a bit more of the icecream at the top (still hiding whether or not it has a cherry of course).  A closer crop on the bottom would eliminate the light reflection on the table.', '2004-03-10 17:52:04.000000', NULL, 1),
