(617560, 63871, 17724, '<td valign="top">Nice idea for this challenge, great composition, perhaps could be improved by backing off on the overhead lighting and adding more direct (frontal) light on the subject. - 8</td>', 'Nice idea for this challenge, great composition, perhaps could be improved by backing off on the overhead lighting and adding more direct (frontal) light on the subject. - 8', '2004-03-10 21:41:37.000000', NULL, 1),
(617563, 63289, 10818, '<td valign="top">What a wonderful shot...very cute, and very well done in B&amp;W.</td>', 'What a wonderful shot...very cute, and very well done in B&W.', '2004-03-10 21:44:25.000000', NULL, 1),
(617565, 63912, 12151, '<td valign="top">Great capture of a sculpture, and it meets the challenge nicely.</td>', 'Great capture of a sculpture, and it meets the challenge nicely.', '2004-03-10 21:46:10.000000', NULL, 1),
