INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(617723, 63882, 14603, '<td valign="top">Very fitting for the challenge.</td>', 'Very fitting for the challenge.', '2004-03-11 06:22:33.000000', NULL, 1),
(617724, 63404, 11181, '<td valign="top">Hmmm... you could have used a longer exposure instead of the flash. It would have given the picture a less harsh effect (hope i''m making sense here)... don''t you think the flash is a bit distracting? Oh well, good attempt and a yummy concept! Good luck!</td>', 'Hmmm... you could have used a longer exposure instead of the flash. It would have given the picture a less harsh effect (hope i''m making sense here)... don''t you think the flash is a bit distracting? Oh well, good attempt and a yummy concept! Good luck!', '2004-03-11 06:25:29.000000', NULL, 1),
(617725, 63959, 11181, '<td valign="top">Wow! The corner behind the girl could have been cropped though... but nevertheless a good concept :D Good luck!</td>', 'Wow! The corner behind the girl could have been cropped though... but nevertheless a good concept :D Good luck!', '2004-03-11 06:27:04.000000', NULL, 1),
(617727, 63889, 14603, '<td valign="top">Nice fresh idea here.<br/>I would have preferred the person to be positioned more to the right or left..as the negative space would have balanced the picture.<br/>However, the idea is a really good one and you deserve to do well with this.<br/>Good luck</td>', 'Nice fresh idea here.I would have preferred the person to be positioned more to the right or left..as the negative space would have balanced the picture.However, the idea is a really good one and you deserve to do well with this.Good luck', '2004-03-11 06:36:22.000000', NULL, 1),
(617741, 63633, 14603, '<td valign="top">Quite a fresh idea here in this image..but for me the angle of view needs altered to make the effect stronger. <br/>The dog is your subject and I would have preferred to see it fill most of the frame and probably taken from the left side and a little to the rear. This would have eliminated all the unnecessary clutter but kept the interesting angle of view. A shallow depth of field would help too.<br/>Hope this is helpful.</td>', 'Quite a fresh idea here in this image..but for me the angle of view needs altered to make the effect stronger. The dog is your subject and I would have preferred to see it fill most of the frame and probably taken from the left side and a little to the rear. This would have eliminated all the unnecessary clutter but kept the interesting angle of view. A shallow depth of field would help too.Hope this is helpful.', '2004-03-11 06:59:43.000000', NULL, 1),
(617742, 63882, 4906, '<td valign="top">The underwear is far too neat on the floor, it should be more chaotic.</td>', 'The underwear is far too neat on the floor, it should be more chaotic.', '2004-03-11 07:02:46.000000', NULL, 1),
(617743, 63672, 14603, '<td valign="top">Of all the dog pictures ..this is my favourite so far.<br/>Great angle of view and nice splash of colour.<br/>Don`t know if the snow will be seen by some as distracting..but I think it adds to the image.<br/>Good luck</td>', 'Of all the dog pictures ..this is my favourite so far.Great angle of view and nice splash of colour.Don`t know if the snow will be seen by some as distracting..but I think it adds to the image.Good luck', '2004-03-11 07:04:12.000000', NULL, 1),
(617745, 63880, 4906, '<td valign="top">I''m not keen on the composition. I''d have preferred the model a little more to the left of the picture. Still one of the best shots of the challenge.</td>', 'I''m not keen on the composition. I''d have preferred the model a little more to the left of the picture. Still one of the best shots of the challenge.', '2004-03-11 07:04:58.000000', NULL, 1),
(617747, 63731, 14603, '<td valign="top">A beautiful dog..expertly photographed.</td>', 'A beautiful dog..expertly photographed.', '2004-03-11 07:07:07.000000', NULL, 1),
(617748, 63864, 14603, '<td valign="top">What a cracking image.More about "portraiture" for me than "off screen expectation" but tremendous work none the less.<br/>I think i can guess the photographer here ?<br/>Superb..10</td>', 'What a cracking image.More about "portraiture" for me than "off screen expectation" but tremendous work none the less.I think i can guess the photographer here ?Superb..10', '2004-03-11 07:11:18.000000', NULL, 1),
(617750, 63237, 14603, '<td valign="top">Bang goes my idea for parallel lines :(<br/>Excellent image though.</td>', 'Bang goes my idea for parallel lines :(Excellent image though.', '2004-03-11 07:13:44.000000', NULL, 1),
(617753, 63426, 14603, '<td valign="top">I`m stretching a bit to find the off screen connection but that doesn`t take away from the image ..which is tremendous.<br/>What a capture</td>', 'I`m stretching a bit to find the off screen connection but that doesn`t take away from the image ..which is tremendous.What a capture', '2004-03-11 07:16:55.000000', NULL, 1),
(617760, 63912, 14603, '<td valign="top">I normally don`t care for images using statues etc...but this is so well done, the lighting, composition and shallow DOF all combine to make this image a winner with me...10</td>', 'I normally don`t care for images using statues etc...but this is so well done, the lighting, composition and shallow DOF all combine to make this image a winner with me...10', '2004-03-11 07:22:15.000000', NULL, 1),
(617762, 63864, 7889, '<td valign="top">Very interesting photograph, which I like very much. The eye''s are amazing. Great capture</td>', 'Very interesting photograph, which I like very much. The eye''s are amazing. Great capture', '2004-03-11 07:23:56.000000', NULL, 1),
(617775, 63766, 15420, '<td valign="top">what in interesting shot.  How the heck was that done?  the only thing I can think of is a big print out behind the girl..  Im not totally sure how it ties into the Theme, but I did expect the horizon to remain constant!</td>', 'what in interesting shot.  How the heck was that done?  the only thing I can think of is a big print out behind the girl..  Im not totally sure how it ties into the Theme, but I did expect the horizon to remain constant!', '2004-03-11 07:45:55.000000', NULL, 1),
