INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(618136, 63622, 14773, '<td valign="top">Clever, but there''s not much detail or else there''s TOO much detail..that''s not much help is it? Sorry...brain fart.</td>', 'Clever, but there''s not much detail or else there''s TOO much detail..that''s not much help is it? Sorry...brain fart.', '2004-03-11 13:15:08.000000', NULL, 1),
(618137, 63882, 14773, '<td valign="top">very cool idea and nice panties ;-) too bad you used a direct flash, looks like a snapshot. 3. With better lighting it would''ve been really good.</td>', 'very cool idea and nice panties ;-) too bad you used a direct flash, looks like a snapshot. 3. With better lighting it would''ve been really good.', '2004-03-11 13:16:06.000000', NULL, 1),
(618138, 63983, 14773, '<td valign="top">Very 70''s horror looking, good job, the grain and over/under exposure work well.5.</td>', 'Very 70''s horror looking, good job, the grain and over/under exposure work well.5.', '2004-03-11 13:18:05.000000', NULL, 1),
(618141, 63768, 14773, '<td valign="top">Very nice idea and photo, the mountain in the background makes you excited to know what''s off to the left that could be BETTER to photograph. 6.</td>', 'Very nice idea and photo, the mountain in the background makes you excited to know what''s off to the left that could be BETTER to photograph. 6.', '2004-03-11 13:19:31.000000', NULL, 1),
(618142, 63987, 14773, '<td valign="top">I love this photo, don''t get the title, but I digress. Great shadows and contrast and relation to the challenge. 6.</td>', 'I love this photo, don''t get the title, but I digress. Great shadows and contrast and relation to the challenge. 6.', '2004-03-11 13:20:08.000000', NULL, 1),
(618143, 63964, 14773, '<td valign="top">sorry, nice photo, but horribly pixelated/grainy...doesn''t look intentional.</td>', 'sorry, nice photo, but horribly pixelated/grainy...doesn''t look intentional.', '2004-03-11 13:20:42.000000', NULL, 1),
(618145, 63552, 14773, '<td valign="top">Not sure what the ''off'' screen expectation is since the storm is visible directly in the photo.</td>', 'Not sure what the ''off'' screen expectation is since the storm is visible directly in the photo.', '2004-03-11 13:21:26.000000', NULL, 1),
(618146, 63956, 14773, '<td valign="top">I''m not getting the correlation with the challenge, feel free to message me with your intention.</td>', 'I''m not getting the correlation with the challenge, feel free to message me with your intention.', '2004-03-11 13:22:12.000000', NULL, 1),
(618148, 63404, 14773, '<td valign="top">mmmm cake mmmm but the direct flash makes the lighting pretty bad</td>', 'mmmm cake mmmm but the direct flash makes the lighting pretty bad', '2004-03-11 13:23:24.000000', NULL, 1),
(618153, 63894, 14773, '<td valign="top">GREAT photo, good idea.  It doesn''t have a lot of pizzazz to really be memorable, but it''s a great take on the challenge and is original. 6.</td>', 'GREAT photo, good idea.  It doesn''t have a lot of pizzazz to really be memorable, but it''s a great take on the challenge and is original. 6.', '2004-03-11 13:24:38.000000', NULL, 1),
(618154, 63526, 14773, '<td valign="top">Nice composition, his expression looks more like he''s in pain to me than he''s confused.</td>', 'Nice composition, his expression looks more like he''s in pain to me than he''s confused.', '2004-03-11 13:25:42.000000', NULL, 1),
(618155, 63796, 14773, '<td valign="top">beautiful photo, lost detail on her lower body, but I like the soft effect.</td>', 'beautiful photo, lost detail on her lower body, but I like the soft effect.', '2004-03-11 13:26:27.000000', NULL, 1),
(618158, 63630, 14773, '<td valign="top">a bird in motion, cool idea, you can see the action but the motion blur takes over the entire bird.</td>', 'a bird in motion, cool idea, you can see the action but the motion blur takes over the entire bird.', '2004-03-11 13:28:26.000000', NULL, 1),
(618159, 63354, 15919, '<td valign="top">Its a funny litle blue eyed fellow youve got there.  Its a fine image and the eye is in focus wich is very important.  But I cant say that it fires up my imagination about whats of-screen.</td>', 'Its a funny litle blue eyed fellow youve got there.  Its a fine image and the eye is in focus wich is very important.  But I cant say that it fires up my imagination about whats of-screen.', '2004-03-11 13:28:55.000000', NULL, 1),
(618163, 63586, 14773, '<td valign="top">very nice capture, right in the action, great moment and fits here very well.  Everything is good, you can see his eyes between his fingers. 7.</td>', 'very nice capture, right in the action, great moment and fits here very well.  Everything is good, you can see his eyes between his fingers. 7.', '2004-03-11 13:30:17.000000', NULL, 1),
(618164, 63847, 14773, '<td valign="top">This would''ve been even better without the image of the person on the left. I like the mystery created with the light on it''s own.</td>', 'This would''ve been even better without the image of the person on the left. I like the mystery created with the light on it''s own.', '2004-03-11 13:31:06.000000', NULL, 1),
(618165, 63242, 14773, '<td valign="top">I can''t see what''s abstract about this, it''s too small to see anything really..sorry!</td>', 'I can''t see what''s abstract about this, it''s too small to see anything really..sorry!', '2004-03-11 13:32:03.000000', NULL, 1),
(618166, 63734, 14773, '<td valign="top">like watching a horror movie in the dark, I like this quite a bit...conveys that eerie feeling....</td>', 'like watching a horror movie in the dark, I like this quite a bit...conveys that eerie feeling....', '2004-03-11 13:32:44.000000', NULL, 1),
(618167, 63813, 10339, '<td valign="top">You captured some great expressions!</td>', 'You captured some great expressions!', '2004-03-11 13:33:16.000000', NULL, 1),
(618168, 63398, 15919, '<td valign="top">Its a fine old car.  I would have given this one a more croping, cuting out the burned out sky, then more colorsaturation and maybe litle more contrast.  Maybe B/W would have been good, suits the subject.<br/>But whats of-screen I cant imagine.  Is it going to blow up or is somebody going to drive it away or what?</td>', 'Its a fine old car.  I would have given this one a more croping, cuting out the burned out sky, then more colorsaturation and maybe litle more contrast.  Maybe B/W would have been good, suits the subject.But whats of-screen I cant imagine.  Is it going to blow up or is somebody going to drive it away or what?', '2004-03-11 13:33:36.000000', NULL, 1),
(618169, 63945, 14773, '<td valign="top">The yellow is a bit bright, hurts my eyes, but this overall is a great photo. Love the fluid lines, shadows and the moment you chose to capture. All works well. 6.</td>', 'The yellow is a bit bright, hurts my eyes, but this overall is a great photo. Love the fluid lines, shadows and the moment you chose to capture. All works well. 6.', '2004-03-11 13:33:41.000000', NULL, 1),
(618170, 63137, 15919, '<td valign="top">Nice colors but the image seems grainy and unsharp.  Cant imagine whats of-screen.</td>', 'Nice colors but the image seems grainy and unsharp.  Cant imagine whats of-screen.', '2004-03-11 13:34:43.000000', NULL, 1),
(618173, 63656, 7889, '<td valign="top">What a beautiful dog. Good colour</td>', 'What a beautiful dog. Good colour', '2004-03-11 13:42:11.000000', NULL, 1),
(618174, 63810, 16957, '<td valign="top">This is an effective interpretation of the challenge. I like the sense of realism and the black and white works well as does the sharp contrast. Well done for an imaginative and well executed shot.</td>', 'This is an effective interpretation of the challenge. I like the sense of realism and the black and white works well as does the sharp contrast. Well done for an imaginative and well executed shot.', '2004-03-11 13:42:20.000000', NULL, 1),
(618176, 63762, 16957, '<td valign="top">Nicely composed with the focus on the foreground person. Evokes a realistic sense of somethign happenign of screen.</td>', 'Nicely composed with the focus on the foreground person. Evokes a realistic sense of somethign happenign of screen.', '2004-03-11 13:43:11.000000', NULL, 1),
(618178, 63737, 16957, '<td valign="top">Beautifully composed and wondeful lighting, textures and DOF. Also - a good interpretation of the challenge.</td>', 'Beautifully composed and wondeful lighting, textures and DOF. Also - a good interpretation of the challenge.', '2004-03-11 13:43:59.000000', NULL, 1),
(618180, 63964, 7889, '<td valign="top">Such a shame this photo is spoiled by the efforts to re-size. I am certain the original looks good.</td>', 'Such a shame this photo is spoiled by the efforts to re-size. I am certain the original looks good.', '2004-03-11 13:45:26.000000', NULL, 1),
(618182, 63880, 16957, '<td valign="top">This is a well composed shot which works well in b&amp;w. it has an editorial feel and good contrast. It is not all that effective in evoking any sense of anythign happening off screen other than the obvious though (removing her bra). This lets it down as a challenge entry.</td>', 'This is a well composed shot which works well in b&w. it has an editorial feel and good contrast. It is not all that effective in evoking any sense of anythign happening off screen other than the obvious though (removing her bra). This lets it down as a challenge entry.', '2004-03-11 13:45:48.000000', NULL, 1),
(618183, 63840, 16957, '<td valign="top">Nicely shot. However I''m left with little in the way of anticiaption as to what''s happening off frame since it is a static composition.</td>', 'Nicely shot. However I''m left with little in the way of anticiaption as to what''s happening off frame since it is a static composition.', '2004-03-11 13:46:55.000000', NULL, 1),
(618184, 63814, 16957, '<td valign="top">Well composed but the title reveals what is happenign off screen which reduces the effectiveness of the idea which is to be oleft with anticipation of something happening that one is uncertain of. the shot could have been improved in this regard by the use of a shallow DOF with the road and background out of focus. That would have left me with a sense of anticipation and wonder.</td>', 'Well composed but the title reveals what is happenign off screen which reduces the effectiveness of the idea which is to be oleft with anticipation of something happening that one is uncertain of. the shot could have been improved in this regard by the use of a shallow DOF with the road and background out of focus. That would have left me with a sense of anticipation and wonder.', '2004-03-11 13:49:13.000000', NULL, 1),
(618187, 63592, 16957, '<td valign="top">This is an amusing shot which I hope does well as it shows a wacky imagination and imaginative take on the challenge. Technically I''d rather not see the plate edges on left or see them all (from top right this doesn''t seem to be a regular circular plate?) The loighting could have been improved on the apple too. There is one bright highlight and the rest is rather underexposed.</td>', 'This is an amusing shot which I hope does well as it shows a wacky imagination and imaginative take on the challenge. Technically I''d rather not see the plate edges on left or see them all (from top right this doesn''t seem to be a regular circular plate?) The loighting could have been improved on the apple too. There is one bright highlight and the rest is rather underexposed.', '2004-03-11 13:51:21.000000', NULL, 1),
(618191, 63575, 7889, '<td valign="top">Great humour and technically good. B&amp;W looks a good choice</td>', 'Great humour and technically good. B&W looks a good choice', '2004-03-11 14:03:25.000000', NULL, 1),
(618194, 63428, 14477, '<td valign="top">Beautiful little girl...a little blurry though.  I really like the picture.</td>', 'Beautiful little girl...a little blurry though.  I really like the picture.', '2004-03-11 14:05:12.000000', NULL, 1),
(618195, 63317, 7889, '<td valign="top">I just think this is a wonderful photograph, not certain about it meeting the challenge but I will be putting this in my favs.</td>', 'I just think this is a wonderful photograph, not certain about it meeting the challenge but I will be putting this in my favs.', '2004-03-11 14:05:35.000000', NULL, 1),
(618198, 63641, 15810, '<td valign="top">Not sure where the "off screen expectation" is here. NIce shot but a little lacking in a focal point just too much going on in th etop half of the photo</td>', 'Not sure where the "off screen expectation" is here. NIce shot but a little lacking in a focal point just too much going on in th etop half of the photo', '2004-03-11 14:07:05.000000', NULL, 1),
(618199, 63586, 15810, '<td valign="top">great action shot, pity your POV kind of merges the two players together.</td>', 'great action shot, pity your POV kind of merges the two players together.', '2004-03-11 14:08:15.000000', NULL, 1),
(618201, 63871, 15810, '<td valign="top">Great shot, fantastic framing. Looks like an advertising shot. really works.</td>', 'Great shot, fantastic framing. Looks like an advertising shot. really works.', '2004-03-11 14:09:12.000000', NULL, 1),
(618203, 63864, 18323, '<td valign="top">nice shot</td>', 'nice shot', '2004-03-11 14:12:05.000000', NULL, 1),
(618206, 63839, 13136, '<td valign="top">The birds are too dim to see with any clarity unless you were going for silhouette style. I don''t really see the challenge in this shot.</td>', 'The birds are too dim to see with any clarity unless you were going for silhouette style. I don''t really see the challenge in this shot.', '2004-03-11 14:20:27.000000', NULL, 1),
(618209, 63941, 11943, '<td valign="top">Cool. Like a movie.</td>', 'Cool. Like a movie.', '2004-03-11 14:24:49.000000', NULL, 1),
(618212, 63987, 11943, '<td valign="top">Surreal. Nice.</td>', 'Surreal. Nice.', '2004-03-11 14:27:31.000000', NULL, 1),
(618213, 63737, 11943, '<td valign="top">Hee hee.</td>', 'Hee hee.', '2004-03-11 14:28:13.000000', NULL, 1),
(618214, 63298, 13136, '<td valign="top">Cute kid. You met the challenge well. There is just something stark about this shot (maybe harsh light?). I still like it though.</td>', 'Cute kid. You met the challenge well. There is just something stark about this shot (maybe harsh light?). I still like it though.', '2004-03-11 14:28:34.000000', NULL, 1),
(618215, 63954, 11943, '<td valign="top">Pretty, but it don''t really match up to the challenge. Well, it was a tough one.<br/></td>', 'Pretty, but it don''t really match up to the challenge. Well, it was a tough one.', '2004-03-11 14:29:18.000000', NULL, 1),
(618216, 63830, 13136, '<td valign="top">Good capture of the expression. I like the black negative space also. Maybe just a bit too much light on the face? Good shot.</td>', 'Good capture of the expression. I like the black negative space also. Maybe just a bit too much light on the face? Good shot.', '2004-03-11 14:29:28.000000', NULL, 1),
(618217, 63575, 11943, '<td valign="top">Hee hee.</td>', 'Hee hee.', '2004-03-11 14:29:55.000000', NULL, 1),
(618219, 63656, 13136, '<td valign="top">Staring off into space does not really make me wonder what the dog is looking at. There is no real expectation.</td>', 'Staring off into space does not really make me wonder what the dog is looking at. There is no real expectation.', '2004-03-11 14:31:29.000000', NULL, 1),
(618220, 63985, 11943, '<td valign="top">Love the expressions.</td>', 'Love the expressions.', '2004-03-11 14:32:01.000000', NULL, 1),
(618221, 63955, 13136, '<td valign="top">Clever. Unique angle on a shot.</td>', 'Clever. Unique angle on a shot.', '2004-03-11 14:32:08.000000', NULL, 1),
(618222, 63198, 11943, '<td valign="top">Freaky</td>', 'Freaky', '2004-03-11 14:32:13.000000', NULL, 1),
(618223, 63912, 13136, '<td valign="top">Definite off-screen expectation on the face. Lighting and composition are well done.</td>', 'Definite off-screen expectation on the face. Lighting and composition are well done.', '2004-03-11 14:32:44.000000', NULL, 1),
(618226, 63388, 13136, '<td valign="top">Good expression and the motion of the hand is just right.  Too bad the face isn''t better focused.</td>', 'Good expression and the motion of the hand is just right.  Too bad the face isn''t better focused.', '2004-03-11 14:34:22.000000', NULL, 1),
(618227, 63641, 13136, '<td valign="top">Don''t you hate it when animals only give you shots of their butts? Maybe a little more ground cropped out and sky cropped in?</td>', 'Don''t you hate it when animals only give you shots of their butts? Maybe a little more ground cropped out and sky cropped in?', '2004-03-11 14:35:22.000000', NULL, 1),
(618228, 63921, 13136, '<td valign="top">The furrowed brow says it all. Nice catch.</td>', 'The furrowed brow says it all. Nice catch.', '2004-03-11 14:35:46.000000', NULL, 1),
(618229, 63799, 13136, '<td valign="top">Challenge met. Face is lacking a bit in focus and too bright. Good expression.</td>', 'Challenge met. Face is lacking a bit in focus and too bright. Good expression.', '2004-03-11 14:36:51.000000', NULL, 1),
(618231, 63400, 13136, '<td valign="top">Nothing says ''attention'' like a cat''s stare. Nice capture. I can''t help wanting to see (more) color in the eyes. Did you desaturate or is that the way they look?</td>', 'Nothing says ''attention'' like a cat''s stare. Nice capture. I can''t help wanting to see (more) color in the eyes. Did you desaturate or is that the way they look?', '2004-03-11 14:37:59.000000', NULL, 1),
(618232, 63786, 13136, '<td valign="top">The raised ears make the challenge. I would rather see the dogs from the front. It seems like we are missing something looking at the back of their heads.</td>', 'The raised ears make the challenge. I would rather see the dogs from the front. It seems like we are missing something looking at the back of their heads.', '2004-03-11 14:38:48.000000', NULL, 1),
(618234, 63813, 11943, '<td valign="top">Clever :)</td>', 'Clever :)', '2004-03-11 14:39:57.000000', NULL, 1),
(618236, 63864, 13136, '<td valign="top">Hauntingly beautiful portrait. Good framing.lighting and focus. The off-screen expectation seems lacking.</td>', 'Hauntingly beautiful portrait. Good framing.lighting and focus. The off-screen expectation seems lacking.', '2004-03-11 14:40:20.000000', NULL, 1),
(618237, 63871, 13136, '<td valign="top">The contrast between the clothes and the white background is enormous. The rope and the top of the hands are a bit overexposed. Challenge met.</td>', 'The contrast between the clothes and the white background is enormous. The rope and the top of the hands are a bit overexposed. Challenge met.', '2004-03-11 14:41:40.000000', NULL, 1),
(618238, 63895, 13136, '<td valign="top">I like the tilt and the edge lighting on the face.</td>', 'I like the tilt and the edge lighting on the face.', '2004-03-11 14:42:47.000000', NULL, 1),
(618240, 63835, 13136, '<td valign="top">Ahh. Dogs that really look like there is something of interest off screen. They almost seem to blend in with the floor as far as color. Good expressions and composition.</td>', 'Ahh. Dogs that really look like there is something of interest off screen. They almost seem to blend in with the floor as far as color. Good expressions and composition.', '2004-03-11 14:43:47.000000', NULL, 1),
(618241, 63453, 13136, '<td valign="top">I like the expressions. The only down, IMO, is the less than sharp focus. Good shot.</td>', 'I like the expressions. The only down, IMO, is the less than sharp focus. Good shot.', '2004-03-11 14:44:55.000000', NULL, 1),
(618242, 63813, 13136, '<td valign="top">Good expressions. Unique idea.</td>', 'Good expressions. Unique idea.', '2004-03-11 14:45:17.000000', NULL, 1),
(618244, 63575, 13136, '<td valign="top">Wonderful expression. Clever idea.</td>', 'Wonderful expression. Clever idea.', '2004-03-11 14:46:39.000000', NULL, 1),
(618249, 63630, 15810, '<td valign="top">Pity the focus is on the table and not the bird. Also not sure where the "off screen expectation" is here?</td>', 'Pity the focus is on the table and not the bird. Also not sure where the "off screen expectation" is here?', '2004-03-11 14:53:46.000000', NULL, 1),
(618252, 63373, 15810, '<td valign="top">Beautiful quirky photo, where is the "off screen expectation" though?</td>', 'Beautiful quirky photo, where is the "off screen expectation" though?', '2004-03-11 14:54:41.000000', NULL, 1),
(618253, 63613, 15810, '<td valign="top">Nice shot, lovely depth of field and looks great as a B&amp;W, well done</td>', 'Nice shot, lovely depth of field and looks great as a B&W, well done', '2004-03-11 14:55:36.000000', NULL, 1),
(618259, 63964, 13136, '<td valign="top">Whoa! Looks like you lost some resolution somewhere. Good composition, but the pixelations are a big drag. Maybe try making the same image smaller so as to compress it a bit.</td>', 'Whoa! Looks like you lost some resolution somewhere. Good composition, but the pixelations are a big drag. Maybe try making the same image smaller so as to compress it a bit.', '2004-03-11 14:59:54.000000', NULL, 1),
(618262, 63734, 13136, '<td valign="top">The composition and lighting are good, but the focus isn''t.</td>', 'The composition and lighting are good, but the focus isn''t.', '2004-03-11 15:01:54.000000', NULL, 1),
(618272, 63796, 18327, '<td valign="top">Very nice!</td>', 'Very nice!', '2004-03-11 15:21:18.000000', NULL, 1),
(618275, 63727, 16912, '<td valign="top">Would like to hear how/where you shot this? My initial thought is it is not in the wild and may not be flying? My favourite shot of the challenge Great feeling of the birds power and concentration on the ''off screen'' prey. Mouse, rabbit or maybe even something bigger?</td>', 'Would like to hear how/where you shot this? My initial thought is it is not in the wild and may not be flying? My favourite shot of the challenge Great feeling of the birds power and concentration on the ''off screen'' prey. Mouse, rabbit or maybe even something bigger?', '2004-03-11 15:24:44.000000', NULL, 1),
(618298, 63182, 10047, '<td valign="top">Excellent shot! Beautiful pup! Good composition. All these dog shots are great. 9</td>', 'Excellent shot! Beautiful pup! Good composition. All these dog shots are great. 9', '2004-03-11 15:46:26.000000', NULL, 1),
(618300, 63945, 4008, '<td valign="top">Great idea, great capture. The light on the face, the strong look, the bar atmosphere, the angle of view, the colors, all contribute to a strong image. If further editing was allowed, I would tone down the yellow, but I don''t think any other changes are needed.</td>', 'Great idea, great capture. The light on the face, the strong look, the bar atmosphere, the angle of view, the colors, all contribute to a strong image. If further editing was allowed, I would tone down the yellow, but I don''t think any other changes are needed.', '2004-03-11 15:47:07.000000', NULL, 1),
(618301, 63835, 10047, '<td valign="top">Beautiful dogs! Great expression. Nice composition. All these dog shots are great! 9</td>', 'Beautiful dogs! Great expression. Nice composition. All these dog shots are great! 9', '2004-03-11 15:48:13.000000', NULL, 1),
(618303, 63731, 10047, '<td valign="top">Beautiful dog. Nice capture and compostion. 9</td>', 'Beautiful dog. Nice capture and compostion. 9', '2004-03-11 15:49:08.000000', NULL, 1),
(618306, 63775, 4008, '<td valign="top">Good expression, a lovely image with great colors and light. Good composition, good fit to theme. Later comment : I keep coming back to this one, it is a simple picture, but very attractive and fitting, the whole atmosphere. One of best in the challenge.</td>', 'Good expression, a lovely image with great colors and light. Good composition, good fit to theme. Later comment : I keep coming back to this one, it is a simple picture, but very attractive and fitting, the whole atmosphere. One of best in the challenge.', '2004-03-11 15:50:18.000000', NULL, 1),
(618307, 63728, 10047, '<td valign="top">Great shot, and nice composition. I like the black iron gate as a background. Might work in the Parallel Line challenge also. Beautiful dog. 9</td>', 'Great shot, and nice composition. I like the black iron gate as a background. Might work in the Parallel Line challenge also. Beautiful dog. 9', '2004-03-11 15:50:28.000000', NULL, 1),
(618308, 63727, 10047, '<td valign="top">Beautiful raptor. Too bad about the Basic Editing rules. I''m sure you wanted to edit the reflection in the eye.</td>', 'Beautiful raptor. Too bad about the Basic Editing rules. I''m sure you wanted to edit the reflection in the eye.', '2004-03-11 15:51:52.000000', NULL, 1),
(618309, 63997, 10047, '<td valign="top">Great capture and expression. Meets the challenge nicely.</td>', 'Great capture and expression. Meets the challenge nicely.', '2004-03-11 15:53:05.000000', NULL, 1),
(618314, 63856, 10047, '<td valign="top">Great shot. Awkward angle for looking off-camera, but still a great capture.</td>', 'Great shot. Awkward angle for looking off-camera, but still a great capture.', '2004-03-11 15:58:08.000000', NULL, 1),
(618315, 63871, 10047, '<td valign="top">Very creative and well done. Nice composition.</td>', 'Very creative and well done. Nice composition.', '2004-03-11 15:59:02.000000', NULL, 1),
(618316, 63863, 10047, '<td valign="top">Well done. Might have tried a closer shot froma lower angle.</td>', 'Well done. Might have tried a closer shot froma lower angle.', '2004-03-11 15:59:55.000000', NULL, 1),
(618323, 63948, 10047, '<td valign="top">Even the cat shots are great in this challenge. Great capture and good composition. The look of concentration and the color around the eyes and nose are excellent. 8</td>', 'Even the cat shots are great in this challenge. Great capture and good composition. The look of concentration and the color around the eyes and nose are excellent. 8', '2004-03-11 16:01:54.000000', NULL, 1),
