(618607, 63133, 7350, '<td valign="top">Nice expression.  I think the focus is just a little too soft, even for a portrait.  Good composition, though.</td>', 'Nice expression.  I think the focus is just a little too soft, even for a portrait.  Good composition, though.', '2004-03-11 21:47:40.000000', NULL, 1),
(618608, 63963, 7350, '<td valign="top">The use of grain is perfect in this image.  I like the composition, the B/W, and the expression.  Very well done.</td>', 'The use of grain is perfect in this image.  I like the composition, the B/W, and the expression.  Very well done.', '2004-03-11 21:48:13.000000', NULL, 1),
(618609, 63404, 7350, '<td valign="top">I''m not sure what super cool thing I''m expecting off screen, unless it''s just the rest of the cake.  Still, nice perspective, good focus and colors.  7.</td>', 'I''m not sure what super cool thing I''m expecting off screen, unless it''s just the rest of the cake.  Still, nice perspective, good focus and colors.  7.', '2004-03-11 21:48:51.000000', NULL, 1),
(618610, 63947, 7350, '<td valign="top">Perfect lighting and composition, and very nice focus and detail.  One of my favorites of the challenge, 9.</td>', 'Perfect lighting and composition, and very nice focus and detail.  One of my favorites of the challenge, 9.', '2004-03-11 21:49:40.000000', NULL, 1),
(618611, 63786, 7350, '<td valign="top">Fits the challenge, but the whites are all washed out, which gives it a very unnatural look.</td>', 'Fits the challenge, but the whites are all washed out, which gives it a very unnatural look.', '2004-03-11 21:50:16.000000', NULL, 1),
(618612, 63979, 7350, '<td valign="top">Interesting idea, good composition.</td>', 'Interesting idea, good composition.', '2004-03-11 21:50:45.000000', NULL, 1),
(618613, 63936, 7350, '<td valign="top">Interesting idea.  Good composition.</td>', 'Interesting idea.  Good composition.', '2004-03-11 21:51:26.000000', NULL, 1),
(618614, 63768, 7350, '<td valign="top">Nice idea.  The cloudy day has made the image a little flat.</td>', 'Nice idea.  The cloudy day has made the image a little flat.', '2004-03-11 21:51:58.000000', NULL, 1),
(618615, 63409, 7350, '<td valign="top">This is the best dog shot I''ve ever seen.  I see the excitement in his eyes.  The soft focus is great, the toning is great, the grain is great.  10.</td>', 'This is the best dog shot I''ve ever seen.  I see the excitement in his eyes.  The soft focus is great, the toning is great, the grain is great.  10.', '2004-03-11 21:53:00.000000', NULL, 1),
(618616, 63871, 7350, '<td valign="top">Nice idea, well executed.  I wish the lights on his hands were just a little softer.</td>', 'Nice idea, well executed.  I wish the lights on his hands were just a little softer.', '2004-03-11 21:53:35.000000', NULL, 1),
(618617, 63633, 7350, '<td valign="top">Nice perspective.  I wish the dog were centered, though, instead of just barely off.  The contrast is a little flat.</td>', 'Nice perspective.  I wish the dog were centered, though, instead of just barely off.  The contrast is a little flat.', '2004-03-11 21:54:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(618618, 63895, 7350, '<td valign="top">Great idea, great lighting.  And your model is perfect for this!  Nice.</td>', 'Great idea, great lighting.  And your model is perfect for this!  Nice.', '2004-03-11 21:54:55.000000', NULL, 1),
(618619, 63749, 7350, '<td valign="top">Interesting.  The noise seems to go well with the theme of the shot.</td>', 'Interesting.  The noise seems to go well with the theme of the shot.', '2004-03-11 21:55:21.000000', NULL, 1),
(618620, 63810, 7350, '<td valign="top">Nice toning job.  The lighting and conversion are fantastic!  10.</td>', 'Nice toning job.  The lighting and conversion are fantastic!  10.', '2004-03-11 21:56:13.000000', NULL, 1),
(618623, 63920, 7350, '<td valign="top">I don''t see that she is expecting anything off-screen.  This looks like a random snap shot, with little thought given to background or lighting or composition.</td>', 'I don''t see that she is expecting anything off-screen.  This looks like a random snap shot, with little thought given to background or lighting or composition.', '2004-03-11 21:56:43.000000', NULL, 1),
(618625, 63762, 7350, '<td valign="top">Nice depth of field, and good posing with the models.  The one in the back perhaps should be without her glasses - there is too much glare there.  7.</td>', 'Nice depth of field, and good posing with the models.  The one in the back perhaps should be without her glasses - there is too much glare there.  7.', '2004-03-11 21:57:29.000000', NULL, 1),
(618626, 63729, 7350, '<td valign="top">Absolutely fantastic.  I love how they are both doing exactly the same thing.  Lighting and focus are very nice.  10.</td>', 'Absolutely fantastic.  I love how they are both doing exactly the same thing.  Lighting and focus are very nice.  10.', '2004-03-11 21:58:07.000000', NULL, 1),
(618628, 63585, 7350, '<td valign="top">Beautiful eye.  Good idea, and nice composition.</td>', 'Beautiful eye.  Good idea, and nice composition.', '2004-03-11 21:59:19.000000', NULL, 1),
(618629, 63332, 7350, '<td valign="top">There are some blown-out highlights on the dog''s face, but I love the green background and the expression of the dog.</td>', 'There are some blown-out highlights on the dog''s face, but I love the green background and the expression of the dog.', '2004-03-11 22:00:04.000000', NULL, 1),
(618630, 63889, 7350, '<td valign="top">Wow, I think the green tinge looks great here!  10.</td>', 'Wow, I think the green tinge looks great here!  10.', '2004-03-11 22:00:41.000000', NULL, 1),
(618631, 63785, 7350, '<td valign="top">I like the darkness of this image.  Nice composition, great idea.</td>', 'I like the darkness of this image.  Nice composition, great idea.', '2004-03-11 22:01:18.000000', NULL, 1),
(618632, 63956, 7350, '<td valign="top">Good shot.  I think it meets the challenge fairly well, though I suppose there are some who do not agree.</td>', 'Good shot.  I think it meets the challenge fairly well, though I suppose there are some who do not agree.', '2004-03-11 22:01:47.000000', NULL, 1),
(618633, 63795, 7350, '<td valign="top">Too soft on the focus, and too bright on some parts of the boy''s arm and hand.</td>', 'Too soft on the focus, and too bright on some parts of the boy''s arm and hand.', '2004-03-11 22:02:33.000000', NULL, 1),
(618635, 63392, 7350, '<td valign="top">This image doesn''t really do much for me.  It''s too cluttered to pull off this contrasty effect.</td>', 'This image doesn''t really do much for me.  It''s too cluttered to pull off this contrasty effect.', '2004-03-11 22:03:28.000000', NULL, 1),
(618636, 63775, 7350, '<td valign="top">Cute child, great colors.  Perhaps the focal plane is just a little too close - I think it rests on the girl''s lower arm rather than on her face.</td>', 'Cute child, great colors.  Perhaps the focal plane is just a little too close - I think it rests on the girl''s lower arm rather than on her face.', '2004-03-11 22:04:21.000000', NULL, 1),
(618637, 63799, 7350, '<td valign="top">I wish the focus were a little sharper here.  I love the expression.  Look at that nose!</td>', 'I wish the focus were a little sharper here.  I love the expression.  Look at that nose!', '2004-03-11 22:05:27.000000', NULL, 1),
(618638, 63354, 7350, '<td valign="top">Good focus and composition.</td>', 'Good focus and composition.', '2004-03-11 22:05:42.000000', NULL, 1),
(618639, 63997, 7350, '<td valign="top">The snow is all very bright.</td>', 'The snow is all very bright.', '2004-03-11 22:06:03.000000', NULL, 1),
(618640, 63847, 7350, '<td valign="top">I''m not exactly sure what your goal was here - while the effect is interesting, it doesn''t convey any sort of emotion or idea to me, rather than just the use of the effect.</td>', 'I''m not exactly sure what your goal was here - while the effect is interesting, it doesn''t convey any sort of emotion or idea to me, rather than just the use of the effect.', '2004-03-11 22:06:40.000000', NULL, 1),
(618642, 63266, 7350, '<td valign="top">The composition of this is fantastic.  I can only guess what he''s expecting off-screen.  From the look on his face, it could be some deep thinking he''s doing there.  Good B/W, nice lighting.  10.</td>', 'The composition of this is fantastic.  I can only guess what he''s expecting off-screen.  From the look on his face, it could be some deep thinking he''s doing there.  Good B/W, nice lighting.  10.', '2004-03-11 22:07:58.000000', NULL, 1),
