(619108, 63633, 6565, '<td valign="top">I really like how the leash leading to the right and the dog looking straight ahead create two points of interest off-screen.  It''s such a calm picture but there''s clearly conflict. :)  Technically, it''s not very interesting, but I rated it high because I really am curious what is off-screen in two directions!</td>', 'I really like how the leash leading to the right and the dog looking straight ahead create two points of interest off-screen.  It''s such a calm picture but there''s clearly conflict. :)  Technically, it''s not very interesting, but I rated it high because I really am curious what is off-screen in two directions!', '2004-03-12 12:31:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(619109, 63586, 6565, '<td valign="top">Darn, if this guy''s hand wasn''t in front of his face, and the other player wasn''t right behind him, I''d say this was perfect!  As it is, it''s right on for meeting the topic.  Almost makes you physically look up! :)</td>', 'Darn, if this guy''s hand wasn''t in front of his face, and the other player wasn''t right behind him, I''d say this was perfect!  As it is, it''s right on for meeting the topic.  Almost makes you physically look up! :)', '2004-03-12 12:33:19.000000', NULL, 1),
(619110, 63439, 6565, '<td valign="top">Meets the topic AND is visually interesting.  I love the one player from the opposite team being positioned so centrally so that the focus goes from him directly off-screen to the action.  Really nice!</td>', 'Meets the topic AND is visually interesting.  I love the one player from the opposite team being positioned so centrally so that the focus goes from him directly off-screen to the action.  Really nice!', '2004-03-12 12:35:31.000000', NULL, 1),
