(624025, 63883, 18552, '<td valign="top">Very clear and well focused photo. It makes me want to see where this bridge leads and why it is there in the first place!</td>', 'Very clear and well focused photo. It makes me want to see where this bridge leads and why it is there in the first place!', '2004-03-16 19:59:42.000000', NULL, 1),
(624027, 63732, 18552, '<td valign="top">Rather gruesome and frightening.</td>', 'Rather gruesome and frightening.', '2004-03-16 20:00:50.000000', NULL, 1),
