INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(625401, 63209, 5792, '<td valign="top">This is one of my top three favorites for this challenge.<br/> <br/>The tones in it are fantastic and you captured your subject just right. The pose fits the challenge well. The adjustments made to it are right on and the framing wonderful. Kudos to you for this excellent image.</td>', 'This is one of my top three favorites for this challenge. The tones in it are fantastic and you captured your subject just right. The pose fits the challenge well. The adjustments made to it are right on and the framing wonderful. Kudos to you for this excellent image.', '2004-03-17 11:42:27.000000', NULL, 0),
(625422, 63729, 6624, '<td valign="top">Congratulations on the Blue...well-deserved and charming.</td>', 'Congratulations on the Blue...well-deserved and charming.', '2004-03-17 11:50:01.000000', NULL, 0),
(625426, 63586, 6624, '<td valign="top">Congratulations on the Red--a difficult challenge for many and you captured it well.</td>', 'Congratulations on the Red--a difficult challenge for many and you captured it well.', '2004-03-17 11:50:47.000000', NULL, 0),
(625438, 63880, 17485, '<td valign="top">Congratulations!  I''m glad this shot placed well!  Very nice.</td>', 'Congratulations!  I''m glad this shot placed well!  Very nice.', '2004-03-17 11:56:24.000000', NULL, 0),
(625444, 63586, 9448, '<td valign="top">Thank you very much for everyone who commented during and after the challenge -- your comments are very much appreciated.<br/> <br/>In case anyone is interested, I used curves to increase the contrast.  Then I used the hue and saturation dialogue to increase the saturation by about 15.  Then I black and whited using the Channel mixer, based mainly upon the blue Channel.  Then I sharpened the picture to my usual Web spec for which the settings are go along -- 300, 0.3, 0.<br/> <br/>Thank you again for the comments, and the voting to get me a ribbon.</td>', 'Thank you very much for everyone who commented during and after the challenge -- your comments are very much appreciated. In case anyone is interested, I used curves to increase the contrast.  Then I used the hue and saturation dialogue to increase the saturation by about 15.  Then I black and whited using the Channel mixer, based mainly upon the blue Channel.  Then I sharpened the picture to my usual Web spec for which the settings are go along -- 300, 0.3, 0. Thank you again for the comments, and the voting to get me a ribbon.', '2004-03-17 11:59:48.000000', NULL, 0),
(625445, 63729, 9448, '<td valign="top">congratulations on winning, excellent shot.</td>', 'congratulations on winning, excellent shot.', '2004-03-17 12:00:22.000000', NULL, 0),
(625450, 63880, 9448, '<td valign="top">I had a feeling you would do well, very good shot and fit the challenge well too.</td>', 'I had a feeling you would do well, very good shot and fit the challenge well too.', '2004-03-17 12:01:35.000000', NULL, 0),
(625557, 63266, 12802, '<td valign="top">LOL, a few folk didn''t see how it met the challenge??  Best part is looking at their entries! :-)<br/> <br/>Well done!</td>', 'LOL, a few folk didn''t see how it met the challenge??  Best part is looking at their entries! :-) Well done!', '2004-03-17 12:48:19.000000', NULL, 0),
(625558, 63841, 12252, '<td valign="top">You did it again, another top ten finisher! Congratulations!</td>', 'You did it again, another top ten finisher! Congratulations!', '2004-03-17 12:48:49.000000', NULL, 0),
(625590, 63180, 16046, '<td valign="top">I thought you would finish much higher, mine did really poor.</td>', 'I thought you would finish much higher, mine did really poor.', '2004-03-17 13:15:11.000000', NULL, 0),
(625824, 63726, 16106, '<td valign="top">This shot was taken at the Santa Clara ( Near San Jose California )<br/>Convention Center when President Bush came to speak at a fund raising luncheon. Security was VERY tight and I missed the arrival so during the speech I took photos of the protesters and supporters and the security there to keep them in line. The crowd was small, well behaved and rather flamboyant. I can''t remember if the sherriff in the forground was smiling at the woman dressed as Wonder Woman,  the Lesbian couple in their wedding dresses, of one of a dozen costumed fringe players.<br/> I shot this from as close as I was allowed to get, across eight lanes of traffic with no tripod, as I said security was polite but very firm.<br/></td>', 'This shot was taken at the Santa Clara ( Near San Jose California )Convention Center when President Bush came to speak at a fund raising luncheon. Security was VERY tight and I missed the arrival so during the speech I took photos of the protesters and supporters and the security there to keep them in line. The crowd was small, well behaved and rather flamboyant. I can''t remember if the sherriff in the forground was smiling at the woman dressed as Wonder Woman,  the Lesbian couple in their wedding dresses, of one of a dozen costumed fringe players. I shot this from as close as I was allowed to get, across eight lanes of traffic with no tripod, as I said security was polite but very firm.', '2004-03-17 15:20:05.000000', NULL, 0),
(625845, 63879, 3447, '<td valign="top">What a shame, Martin, missing the Brown Ribbon by only seven places.   Keep trying, and better luck next time.</td>', 'What a shame, Martin, missing the Brown Ribbon by only seven places.   Keep trying, and better luck next time.', '2004-03-17 15:33:51.000000', NULL, 0),
(625912, 63729, 772, '<td valign="top">Excellent photo and congrats on a blue ribbon :)  I know how hard it can be to catch Jacko and Kiwi in a single photograph.  It seems that they were both distracted by a female monkey that was in the tree above them :)</td>', 'Excellent photo and congrats on a blue ribbon :)  I know how hard it can be to catch Jacko and Kiwi in a single photograph.  It seems that they were both distracted by a female monkey that was in the tree above them :)', '2004-03-17 16:06:48.000000', NULL, 0),
(626019, 63787, 6624, '<td valign="top">Congratulations, I am so glad this got the attention it deserved.</td>', 'Congratulations, I am so glad this got the attention it deserved.', '2004-03-17 16:52:04.000000', NULL, 0),
(626268, 63987, 205, '<td valign="top">This photo was taken at the downtown skatepark in salem oregon on top ot the pyramid. Thats me with the big hair and forest is the one standing next to me. I bumped the contrast way high.</td>', 'This photo was taken at the downtown skatepark in salem oregon on top ot the pyramid. Thats me with the big hair and forest is the one standing next to me. I bumped the contrast way high.', '2004-03-17 17:46:36.000000', NULL, 0),
(626347, 63526, 1368, '<td valign="top">Yes its a flying man with three nipples and a siamese dwarf twin with haemorrhoid stuck on his forehead</td>', 'Yes its a flying man with three nipples and a siamese dwarf twin with haemorrhoid stuck on his forehead', '2004-03-17 18:05:07.000000', NULL, 0),
(626364, 63672, 18191, '<td valign="top">Thanks Geewhy, and everyone else for your comments.</td>', 'Thanks Geewhy, and everyone else for your comments.', '2004-03-17 18:26:31.000000', NULL, 0),
(626400, 63880, 6624, '<td valign="top">Congratulations on the third place - a strong image and well done.</td>', 'Congratulations on the third place - a strong image and well done.', '2004-03-17 18:52:05.000000', NULL, 0),
(626401, 63613, 12809, '<td valign="top">I would''ve thought this would have done better!</td>', 'I would''ve thought this would have done better!', '2004-03-17 18:53:00.000000', NULL, 0),
(626641, 63830, 554, '<td valign="top">nice photo.... I thought it would place much higher.</td>', 'nice photo.... I thought it would place much higher.', '2004-03-17 22:35:49.000000', NULL, 0),
(626935, 63653, 11181, '<td valign="top">One of my favorites in the challenge.. should''ve made into the top 10 atleast! But i guess 28 out of 186 IS pretty good if you think about it. :) I gave you a 9 on this. You really captured the challenge criteria in this shot... Excellent on the technicals btw.</td>', 'One of my favorites in the challenge.. should''ve made into the top 10 atleast! But i guess 28 out of 186 IS pretty good if you think about it. :) I gave you a 9 on this. You really captured the challenge criteria in this shot... Excellent on the technicals btw.', '2004-03-18 04:49:03.000000', NULL, 0),
(627109, 63867, 3765, '<td valign="top">Thanks for the many positive comments I was given on my entry. The photo was shot on a very gloomy day at the Amsterdam Zoo. Lighting conditions were bad and working with a long telephoto lens required high shutter speeds to avoid camera-shake. Furthermore, when seeing the Oryxs in this pose I had to close the aperture a lot to acquire the appropriate depth of field and hence I had to push up the ISO level to 800. Photographing against the sky I had to adjust the values with one stop to still be able to get some detail in the animals. This caused the sky to become washed out. Believe me, I would have enjoyed taking this picture on a sunny day in Africa but this had to do. The photo took some cropping and then some adjustment of the levels. I realize now that I also could have played around a bit with sharpening.</td>', 'Thanks for the many positive comments I was given on my entry. The photo was shot on a very gloomy day at the Amsterdam Zoo. Lighting conditions were bad and working with a long telephoto lens required high shutter speeds to avoid camera-shake. Furthermore, when seeing the Oryxs in this pose I had to close the aperture a lot to acquire the appropriate depth of field and hence I had to push up the ISO level to 800. Photographing against the sky I had to adjust the values with one stop to still be able to get some detail in the animals. This caused the sky to become washed out. Believe me, I would have enjoyed taking this picture on a sunny day in Africa but this had to do. The photo took some cropping and then some adjustment of the levels. I realize now that I also could have played around a bit with sharpening.', '2004-03-18 08:34:50.000000', NULL, 0),
(627292, 63880, 3765, '<td valign="top">I gave this photo a 7 whilst viewing. I could not find anything in the photo expecting anything off-screen. Now I realize that I am. Congratulations. You taught me a lesson.</td>', 'I gave this photo a 7 whilst viewing. I could not find anything in the photo expecting anything off-screen. Now I realize that I am. Congratulations. You taught me a lesson.', '2004-03-18 11:24:44.000000', NULL, 0),
(627293, 63729, 5728, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by jmsetzler:</b></div><hr/><i> I know how hard it can be to catch Jacko and Kiwi in a single photograph.  It seems that they were both distracted by a female monkey that was in the tree above them :) </i></td></tr></table> <br/> <br/>Hahahahahaha..... :)</td>', 'Originally posted by jmsetzler: I know how hard it can be to catch Jacko and Kiwi in a single photograph.  It seems that they were both distracted by a female monkey that was in the tree above them :)   Hahahahahaha..... :)', '2004-03-18 11:25:42.000000', NULL, 0),
(627393, 63948, 9763, '<td valign="top">I would like to thank everyone for their comments!  I know cat pictures are not too popular for high marks, but any subject can convey a message, and I wanted to show that with my "off screen expectation" photo.  I love pet photography, and plan to get better and better at it!!!</td>', 'I would like to thank everyone for their comments!  I know cat pictures are not too popular for high marks, but any subject can convey a message, and I wanted to show that with my "off screen expectation" photo.  I love pet photography, and plan to get better and better at it!!!', '2004-03-18 12:35:54.000000', NULL, 0),
(627751, 63729, 16301, '<td valign="top">A beautiful photo with great detail and DOF. Congrats on the ribbon!<br/> <br/>Good luck...</td>', 'A beautiful photo with great detail and DOF. Congrats on the ribbon! Good luck...', '2004-03-18 16:54:53.000000', NULL, 0),
(627753, 63586, 16301, '<td valign="top">This is an excellent photo. Congrats on your first ribbon!<br/> <br/>Best of luck to you...</td>', 'This is an excellent photo. Congrats on your first ribbon! Best of luck to you...', '2004-03-18 16:56:29.000000', NULL, 0),
(627895, 63880, 15497, '<td valign="top">Where is the rest of the picture? :-)<br/> <br/>Love this picture, very well done! Congratulations with a ribbon!<br/></td>', 'Where is the rest of the picture? :-) Love this picture, very well done! Congratulations with a ribbon!', '2004-03-18 19:42:47.000000', NULL, 0),
(628226, 63552, 17551, '<td valign="top">Thanks for helpful comments.. no polarising filter was used (unfortunately I dont have one)<br/>It was not a reflection, but two different cloud fronts.<br/><br/><i>Message edited by author 2004-03-19 01:09:03.</i></td>', 'Thanks for helpful comments.. no polarising filter was used (unfortunately I dont have one)It was not a reflection, but two different cloud fronts.', '2004-03-19 01:08:15.000000', '2004-03-19 01:09:03.000000', 0),
(628289, 63575, 12896, '<td valign="top">hahahahah  awesome shot!</td>', 'hahahahah  awesome shot!', '2004-03-19 03:50:54.000000', NULL, 0),
(628317, 63880, 17507, '<td valign="top">hahaha. fabulous. would have given a 9 at least.</td>', 'hahaha. fabulous. would have given a 9 at least.', '2004-03-19 04:50:53.000000', NULL, 0),
(628539, 63266, 14700, '<td valign="top">In regards to "Old man and the Seat".  I saw him from accross the street.  Then I fliped up the LCD screen on my E-10 and pretended to fiddle with it at my waist as I walked past and got off two shots.  So no, it wasn''t posed.<br/> <br/>I happen to be in San Fran for an NAPP conference.</td>', 'In regards to "Old man and the Seat".  I saw him from accross the street.  Then I fliped up the LCD screen on my E-10 and pretended to fiddle with it at my waist as I walked past and got off two shots.  So no, it wasn''t posed. I happen to be in San Fran for an NAPP conference.', '2004-03-19 11:18:45.000000', NULL, 0),
(629024, 63959, 17203, '<td valign="top">Thanks for the comments! This came out much better than I expected given the tight quarters and difficult lighting situation. I am simply astounded at the number of people who didn''t see this as an Off-Screen Expectation. It''s pretty darn obvious! No, the marlin isn''t on-screen. We call that thing on the right a shadow... it''s the result of light shining on the object not visible on the screen.  ;-)</td>', 'Thanks for the comments! This came out much better than I expected given the tight quarters and difficult lighting situation. I am simply astounded at the number of people who didn''t see this as an Off-Screen Expectation. It''s pretty darn obvious! No, the marlin isn''t on-screen. We call that thing on the right a shadow... it''s the result of light shining on the object not visible on the screen.  ;-)', '2004-03-19 18:38:59.000000', NULL, 0),
(629304, 63867, 2217, '<td valign="top">Wonderful shot John, it should have scored much higher.  Excellent work.</td>', 'Wonderful shot John, it should have scored much higher.  Excellent work.', '2004-03-20 02:59:13.000000', NULL, 0),
(629418, 63428, 14578, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Tallbloke:</b></div><hr/><i> This feels like a cropped holiday shot rather thana photo in its own right. I''d love to know if this is chopped out of another photo?. The focus is out but otherwise its a lovely image and a very beautiful little girl. </i></td></tr></table> <br/> <br/>I was watching a marriage party at the nearby marina from my balcony. I had the camera out incase a good shot came by. I saw the girl run to the bride holding out the flowers, unfortunately, I was too far to get a closeup of her even with a 300mm lens. She was the only subject in the frame.</td>', 'Originally posted by Tallbloke: This feels like a cropped holiday shot rather thana photo in its own right. I''d love to know if this is chopped out of another photo?. The focus is out but otherwise its a lovely image and a very beautiful little girl.   I was watching a marriage party at the nearby marina from my balcony. I had the camera out incase a good shot came by. I saw the girl run to the bride holding out the flowers, unfortunately, I was too far to get a closeup of her even with a 300mm lens. She was the only subject in the frame.', '2004-03-20 08:24:37.000000', NULL, 0),
(629563, 63929, 1531, '<td valign="top">That''s a cute cuddly boy you''ve got Jacko. I that a Blue-Steel (Zoolander) look on is face? =)<br/>Will probably be a super-male-model in a couple of years.</td>', 'That''s a cute cuddly boy you''ve got Jacko. I that a Blue-Steel (Zoolander) look on is face? =)Will probably be a super-male-model in a couple of years.', '2004-03-20 14:29:45.000000', NULL, 0),
(629584, 63729, 9964, '<td valign="top">thanks for all the wonderful comments :)</td>', 'thanks for all the wonderful comments :)', '2004-03-20 15:35:29.000000', NULL, 0),
