(632971, 63880, 16000, '<td valign="top">this may be one of the most sexually intriguing photos I have seen lately.  nice contrast and framing.  the bra hanging from the anonymous hand and attached to the faceless body is remarkable.  the toning in this BW image is also very nice.</td>', 'this may be one of the most sexually intriguing photos I have seen lately.  nice contrast and framing.  the bra hanging from the anonymous hand and attached to the faceless body is remarkable.  the toning in this BW image is also very nice.', '2004-03-23 06:55:40.000000', NULL, 0),
(633206, 63729, 4851, '<td valign="top">Congrats on a well deserved 1st place. They look sooooo fluffy, like to put my hand on it (and pull their ears :) )</td>', 'Congrats on a well deserved 1st place. They look sooooo fluffy, like to put my hand on it (and pull their ears :) )', '2004-03-23 09:30:42.000000', NULL, 0),
